-- May Collections. Apply only in the complete matched batch.
DELIMITER $$
BEGIN NOT ATOMIC
    DECLARE EXIT HANDLER FOR SQLEXCEPTION BEGIN ROLLBACK; RESIGNAL; END;
    START TRANSACTION;

    IF (SELECT COUNT(*) FROM zone WHERE id IN(6400,6401) OR zoneidnumber IN(763,764) OR short_name IN('chelsithreborn','poshadow')) <> 0 OR
    (SELECT COUNT(*) FROM doors WHERE zone=CONVERT(0x74686567726579 USING utf8mb4) AND version IN(-1,0) AND doorid=200) <> 0 OR
    (SELECT COUNT(*) FROM doors WHERE zone=CONVERT(0x6368656c736974687265626f726e USING utf8mb4) AND version IN(-1,0) AND doorid=200) <> 0 OR
    (SELECT COUNT(*) FROM doors WHERE zone=CONVERT(0x7665787468616c USING utf8mb4) AND version IN(-1,0) AND doorid=200) <> 0 OR
    (SELECT COUNT(*) FROM doors WHERE zone=CONVERT(0x706f736861646f77 USING utf8mb4) AND version IN(-1,0) AND doorid=200) <> 0 OR
    (SELECT COUNT(*) FROM doors WHERE zone=CONVERT(0x6368656c736974687265626f726e USING utf8mb4) AND version IN(-1,0) AND doorid=201) <> 0 OR
    (SELECT COUNT(*) FROM doors WHERE zone=CONVERT(0x6368656c736974687265626f726e USING utf8mb4) AND version IN(-1,0) AND doorid=202) <> 0 OR
    (SELECT COUNT(*) FROM doors WHERE `id` IN (304098720,304098721,304098722,304098723,304098724,304098725)) <> 0 THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='May Collections April zone or door address occupied';
    END IF;

    INSERT INTO `zone` (`id`,`zoneidnumber`,`version`,`short_name`,`long_name`,`expansion`,`map_file_name`,`safe_x`,`safe_y`,`safe_z`,`safe_heading`,`ruleset`,`underworld`,`minclip`,`maxclip`,`canbind`,`cancombat`,`canlevitate`,`castoutdoor`,`ztype`,`zone_exp_multiplier`) VALUES
        (6400,763,0,CONVERT(0x6368656c736974687265626f726e USING utf8mb4),CONVERT(0x4368656c73697468205265626f726e USING utf8mb4),19,CONVERT(0x6368656c736974687265626f726e USING utf8mb4),0,-574,2.05,0,1,-1500,500,3000,1,1,1,1,255,0),
        (6401,764,0,CONVERT(0x706f736861646f77 USING utf8mb4),CONVERT(0x506c616e65206f6620536861646f77 USING utf8mb4),19,CONVERT(0x706f736861646f77 USING utf8mb4),203.5939,-485.4966,-31.4,0,1,-1500,500,3000,1,1,1,1,255,0);

    IF ROW_COUNT() <> 2 THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='May Collections affected rows mismatch: April zones';
    END IF;

    INSERT INTO `doors` (`id`,`doorid`,`zone`,`version`,`name`,`pos_x`,`pos_y`,`pos_z`,`heading`,`opentype`,`dest_zone`,`dest_instance`,`dest_x`,`dest_y`,`dest_z`,`dest_heading`,`size`,`client_version_mask`) VALUES
        (304098720,200,CONVERT(0x74686567726579 USING utf8mb4),0,CONVERT(0x4f424a5f46534352595354414c42 USING utf8mb4),1349.2715,1472.2976,-85.213,0,57,CONVERT(0x6368656c736974687265626f726e USING utf8mb4),0,0,-574,2.05,0,75,4294967295),
        (304098721,200,CONVERT(0x6368656c736974687265626f726e USING utf8mb4),0,CONVERT(0x4f424a5f46534352595354414c42 USING utf8mb4),0,-598,-1.95,0,57,CONVERT(0x74686567726579 USING utf8mb4),0,1349.2715,1352.2976,-8.5,0,75,4294967295),
        (304098722,200,CONVERT(0x7665787468616c USING utf8mb4),0,CONVERT(0x4f424a5f46534352595354414c42 USING utf8mb4),-899.1181,-220.2623,-43.998,0,57,CONVERT(0x706f736861646f77 USING utf8mb4),0,203.5939,-485.4966,-31.4,0,75,4294967295),
        (304098723,200,CONVERT(0x706f736861646f77 USING utf8mb4),0,CONVERT(0x4f424a5f46534352595354414c42 USING utf8mb4),203.5939,-509.4966,-35.446,0,57,CONVERT(0x7665787468616c USING utf8mb4),0,-875.1181,-220.2623,-40,0,75,4294967295),
        (304098724,201,CONVERT(0x6368656c736974687265626f726e USING utf8mb4),0,CONVERT(0x4f424a5f504f5254414c5f315354414745 USING utf8mb4),-250.4585,893.97,321.122,0,57,CONVERT(0x6368656c736974687265626f726e USING utf8mb4),0,5.9399,993.6438,146.41,0,75,4294967295),
        (304098725,202,CONVERT(0x6368656c736974687265626f726e USING utf8mb4),0,CONVERT(0x4f424a5f504f5254414c5f315354414745 USING utf8mb4),5.9399,975.6438,142.41,0,57,CONVERT(0x6368656c736974687265626f726e USING utf8mb4),0,-250.4585,911.97,324.233,0,75,4294967295);

    IF ROW_COUNT() <> 6 THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='May Collections affected rows mismatch: April crystal and aqueduct doors';
    END IF;

    COMMIT;
END$$
DELIMITER ;
